mapper.select:
SELECT DISTINCT organization.id, (SELECT GROUP_CONCAT(o.organization_name ORDER BY LENGTH(o.organization_path) ASC SEPARATOR '·') FROM sys_organization o WHERE organization.organization_path LIKE CONCAT(o.organization_path, '%')) AS organization_name, organization.organization_type, organization.parent_id, organization.organization_path FROM sys_organization organization WHERE organization.status = 'ENABLED' AND organization.effective_status = 'ENABLED' AND EXISTS ( SELECT 1 FROM sys_organization_admin organization_admin JOIN sys_organization administrator_root ON administrator_root.id = organization_admin.organization_id WHERE organization_admin.user_id = #{userId} AND administrator_root.status = 'ENABLED' AND administrator_root.effective_status = 'ENABLED' AND organization.organization_path LIKE CONCAT(administrator_root.organization_path, '%') )
AND organization.organization_type IN ('SCHOOL', 'TRAINING_INSTITUTION') AND organization.organization_type = #{organizationType}
ORDER BY organization.organization_path, organization.id

SELECT DISTINCT organization.id, (SELECT GROUP_CONCAT(o.organization_name ORDER BY LENGTH(o.organization_path) ASC SEPARATOR '·') FROM sys_organization o WHERE organization.organization_path LIKE CONCAT(o.organization_path, '%')) AS organization_name, organization.organization_type, organization.parent_id, organization.organization_path FROM edu_teacher_class teacher_class JOIN sys_organization organization ON organization.id = teacher_class.class_organization_id WHERE teacher_class.teacher_user_id = #{userId} AND teacher_class.status = 'ACTIVE' AND organization.status = 'ENABLED' AND organization.effective_status = 'ENABLED'
AND organization.organization_type IN ('SCHOOL', 'TRAINING_INSTITUTION') AND organization.organization_type = #{organizationType}
ORDER BY organization.organization_path, organization.id
